SZGame3D.runProject(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame3D.restart());
  // Ao iniciar
  const cena = SZGame3D.createFullscreenScene("#c4e2df");
  SZGame3D.frameScene(cena, 25, 2, 16);
  const jardim = SZGame3D.createModelFile(cena, "jardim-acolhedor", 25.18);
  SZGame3D.setPosition(jardim, 0, 2.35, 0);
  const regador = SZGame3D.createModelFile(cena, "regador-azul", 1.95);
  SZGame3D.setPosition(regador, -2, 0.53, -2);
  const flor = SZGame3D.createModelFile(cena, "flor-do-jardim", 1.76);
  SZGame3D.setPosition(flor, 5, 0.83, 1);
  const personagem = SZGame3D.createModelFile(cena, "aventureiro", 1.66);
  SZGame3D.setPosition(personagem, -7, 0.8, 1);
  SZGame3D.walkArea(personagem, -9, 9, -4, 4);
  SZGame3D.walkAnimations(personagem, "parado", "andando");
  let aviso = "Recolha o regador e leve o personagem até a flor.";
  let temRegador = false;
  let ganhou = false;
  SZGame3D.hudText("bottom-center", "Setas ou WASD: andar. R: nova partida.");
  // Quando acontecer
  SZGame3D.onKey("KeyR", () => {
    SZGame3D.restart();
  });
  SZGame3D.onTouch(personagem, regador, () => {
    SZGame3D.setVisible(regador, "hide");
    temRegador = true;
    aviso = "Você pegou o regador! Agora vá até a flor.";
  });
  SZGame3D.onTouch(personagem, flor, () => {
    if (!ganhou) {
      if (temRegador) {
        SZGame3D.playAnimation(flor, "florescer", "uma-vez");
        ganhou = true;
        aviso = "A flor abriu! Você fez o jardim florescer.";
      } else {
        aviso = "Busque o regador primeiro. A flor espera por você.";
      }
    }
  });
  // Enquanto estiver rodando
  SZGame3D.animate(cena, () => {
    SZGame3D.topDown(personagem, 4);
    SZGame3D.hudText("top-center", aviso);
  });
});

